"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a moonstone Quest', 'author': 'Signature original', 'genre': 'Talking Animals', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "That night the Frost Giant's shadow fell over the Whispering Glade: the brook ran backwards, the mushrooms glowed red, the stars went out one by one. Ember held a moonstone tight. It pulsed, warm as a heartbeat.\n\n'We have to fix this,' Ember said. a brave mouse nodded, brave and small. 'The stories say a moonstone can. The stories also say it's dangerous.' Ember grinned. 'The best things are.'\n\nEmber found a moonstone on the first day of spring, under the oldest oak in the Whispering Glade, where the fireflies danced like sparks. It glowed. Things that glow, Ember's grandmother always said, are either magic or trouble. Often both."}, {'n': 2, 'title': 'The Journey', 'text': "They escaped by brook-light, laughing and shaking. a moonstone glowed brighter, as if proud. Ember was starting to understand: it wasn't just a magical object. It was a friend, too.\n\nThey met the wise owl at the crossroads, who asked a riddle: 'What grows when shared?' Ember answered, 'even small friends are mighty — I mean, kindness!' The owl hooted approval and gave them a feather for the road.\n\nthe Frost Giant's minions — shadow crows with eyes like coals — attacked at the hollow hill. a brave mouse was so brave that Ember nearly cried: small teeth, loud courage, and a plan involving the singing shell — no, a moonstone — and perfect timing."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "the Frost Giant's jar cracked. A single star escaped — then another, then a flood of starlight, pouring back to the Whispering Glade. the Frost Giant shrank with every star, smaller, smaller, till only a grumble remained. The Grumble King, indeed.\n\nThe battle was strange and wonderful: a moonstone's light against the Frost Giant's dark, Ember's courage against the Frost Giant's spite, a brave mouse's loyalty against everything. Light, it turns out, is very stubborn.\n\nEmber held up a moonstone. 'Not this,' Ember said. 'This chose me.' the Frost Giant laughed — a sound like dead leaves — and sent the shadow crows. a brave mouse met them with the owl's feather and total fearlessness."}, {'n': 4, 'title': 'Starlight Restored', 'text': "a moonstone chose to stay with Ember — or Ember chose to stay with it; by now they weren't sure there was a difference. It sits by the bed, glowing softly, a nightlight of pure story.\n\nthe Frost Giant's grumble was kept in a jar on the mantel, as a reminder. On quiet nights it mutters. Ember finds it comforting: proof that dark can be made small, and kept.\n\neven small friends are mighty — Ember wrote it in the family book, under the date, in the careful letters of someone who means it forever."}, {'n': 5, 'title': 'The Promise Kept', 'text': "New children come to hear the story, and Ember tells it true: the fear, the laughter, the moment it almost went wrong. 'Were you scared?' they ask. 'Terrified,' Ember says. 'That's what brave is.'\n\nEmber grew, as heroes do, but never grew out of the Whispering Glade. Every spring they check the old oak. Every night a moonstone glows. Every tale a brave mouse tells starts, 'When we saved the stars...'\n\nthe Whispering Glade thrives: the enchanted forest enchants, the glade whispers kindly, the meadow moonlights. All because one child picked up a moonstone and one friend said 'together.'"}, {'n': 6, 'title': 'Bedtime', 'text': "And now it's bedtime in the Whispering Glade, and a moonstone glows soft, and a brave mouse is telling the story one more time, to one more sleepy listener. 'The end,' a brave mouse says.\n\n'Again,' says the listener. It is always 'again.' The best stories are.\n\neven small friends are mighty. Goodnight."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

